const D = { density:.5, energy:.55, hue:210, speed:1, scale:1, x:.5, y:.5, style:'stained_glass', act:'vespers', seed:0, gloom:.6, sway:.5 };
const P = Object.assign({}, D, (window.state.P && window.state.P.__SLOT__) || {});
const S = window.state.__SLOT__ || (window.state.__SLOT__ = {});
const K = window.state.clk || { t:0, cps:.5, beat:0, bar:0, cyc:0, phase:0, pulse:0, swell:0, section:0, intensity:.6, fps:60 };
const A = window.state.audio || { bass:0, lowmid:0, mid:0, treble:0, rms:0, fft:[] };

const clp=(v,a,b)=>Math.max(a,Math.min(b,v));
const frc=v=>v-Math.floor(v);
const md=(a,n)=>((a%n)+n)%n;
const fr=i=>{const s=Math.sin(i*127.1+P.seed*311.7)*43758.5453;return s-Math.floor(s);};
const lrp=(a,b,t)=>a+(b-a)*t;

const W=width,Hh=height,u=Math.min(W,Hh);
const H=md(P.hue,360);
const style=P.style;
const glass=style==='stained_glass', chi=style==='chiaroscuro', ink=style==='ink', wire=style==='wireframe', therm=style==='thermal';
const en=P.energy*(.5+.5*K.intensity);
// act: vespers = light climbs with section; matins = steady bright, dawn service
const act=P.act;
const lumClimb = act==='matins' ? 0.7 : clp(0.25+K.section/7*0.75, 0, 1);

// t0 guard
if(S.lastBeat==null||K.beat<S.lastBeat)S.lastBeat=K.beat;
S.lastBeat=K.beat;

// rose window anchor
const rx=P.x*W, ry=Hh*(0.15+ (P.y-0.5)*0.1);
const rR=u*0.11*(0.8+P.scale*0.5);

// heat/jewel color for a ray index
function rayCol(i,n){
  const f=i/Math.max(1,n-1);
  if(therm){ const h=lrp(280,20,f); return [md(h,360),85,100]; }         // magenta->red heat ramp
  if(chi) return [md(H,360),6,100];
  if(ink) return [md(H,360),10,86];
  if(wire) return [md(H+f*60,360),70,100];
  return [md(H + (f-0.5)*140 + Math.sin(i*2.4)*30,360), 74, 100];        // jewel spread
}

// ---- static interior buffer (keyed size+style+seed+hue+gloom) ----
const key=W+'x'+Hh+':'+style+':'+P.seed+':'+Math.round(H/8)+':'+Math.round(P.gloom*4)+':'+Math.round(P.scale*3);
if(!S.base||S.key!==key){
  S.key=key;
  const g=createGraphics(W,Hh); g.colorMode(HSB,360,100,100,100); g.noStroke();
  const baseB=lrp(24,6,clp(P.gloom,0,1));
  // vault gradient (dark top, faint floor light)
  for(let i=0;i<90;i++){const f=i/89; g.fill(md(H,360),chi||therm?8:34, lrp(baseB*0.4, baseB+8, f<0.7?f/0.7*0.5: 0.5+(f-0.7)/0.3*0.9)); g.rect(0,i*Hh/90-1,W,Hh/90+2);}
  // floor
  const fy=0.82*Hh;
  g.fill(md(H,360),chi?4:18, baseB+10); g.rect(0,fy,W,Hh-fy);
  // reflection strip
  g.fill(md(H+20,360),20,baseB+18,30); g.rect(0,fy,W,u*0.02);

  // columns (arcade) — draw pairs receding
  const nCol=5;
  for(let i=0;i<nCol;i++){
    const side=i/(nCol-1); // 0..1 left->right
    const cx=lrp(W*0.06,W*0.94,side);
    const cw=u*0.05*(0.8+Math.abs(side-0.5)*0.9);
    const top=Hh*0.06, bot=fy;
    if(wire){
      g.noFill(); g.stroke(md(H+30,360),60,100,70); g.strokeWeight(Math.max(1,u*0.0015));
      g.rect(cx-cw/2,top,cw,bot-top);
      // gothic pointed arch
      g.line(cx-cw/2,top,cx,top-u*0.05); g.line(cx+cw/2,top,cx,top-u*0.05);
      g.noStroke();
    } else {
      const cB=chi?lrp(4,30,side):lrp(baseB*0.5,baseB*1.4,fr(i+1));
      g.fill(md(H,360),ink?12:22,cB); g.rect(cx-cw/2,top,cw,bot-top);
      g.fill(0,0,0,30); g.rect(cx+cw*0.18,top,cw*0.32,bot-top); // shaded flute
      g.fill(0,0,100,ink?8:16); g.rect(cx-cw*0.5,top,cw*0.14,bot-top); // lit edge
      // capital
      g.fill(md(H,360),20,cB*1.1); g.rect(cx-cw*0.62,top,cw*1.24,u*0.02);
    }
  }

  // rose window tracery (baked, dim; live glow added on top)
  g.push(); g.translate(rx,ry);
  const petals=12;
  for(let p=0;p<petals;p++){
    const a=p/petals*6.2832;
    const col=rayCol(p%6,6);
    g.fill(col[0], wire?70:(chi?8:66), wire?100:(chi?60:64), wire?40:55);
    if(wire){g.noFill(); g.stroke(col[0],70,100,60); g.strokeWeight(1);}
    g.push(); g.rotate(a);
    g.ellipse(rR*0.55,0,rR*0.5,rR*0.28);
    g.pop();
  }
  g.noStroke();
  g.fill(chi?0:md(H,360),chi?0:40,chi?90:70,60); g.ellipse(0,0,rR*0.5,rR*0.5);
  g.noFill(); g.stroke(0,0,10,80); g.strokeWeight(Math.max(1.5,u*0.003)); g.ellipse(0,0,rR*2,rR*2); g.noStroke();
  g.pop();

  // grain
  const gn=Math.round(2600*(0.4+P.gloom));
  for(let i=0;i<gn;i++){const px=fr(i*3+700)*W,py=fr(i*3+701)*Hh,aa=fr(i*3+702); g.fill(0,0,aa<0.5?100:0, 3.5*(0.4+P.gloom)); g.rect(px,py,1.4,1.4);}
  S.base=g;
  S.dustSeed=P.seed; S.dust=null;
}
image(S.base,0,0,W,Hh);

// ---- seed dust motes ----
if(S.dust==null||S.dustSeed!==P.seed){
  S.dustSeed=P.seed; S.dust=[];
  for(let i=0;i<110;i++) S.dust.push({x:fr(i*4+1),y:fr(i*4+2),s:0.3+fr(i*4+3)*0.9,ph:fr(i*4+4)*6.2832,sp:0.3+fr(i*4+5)});
}

// ---- god-rays (swing via K.t = real-time motion floor) ----
const nRay=Math.max(3,Math.round(lrp(4,12,clp(P.density,0,1))));
const swingAmp=(0.10+P.sway*0.35)*(0.5+en);
const globalSwing=Math.sin(K.t*0.22*P.speed)*swingAmp;
const bright=lumClimb*(0.55+en*0.6) + K.swell*0.18 + A.bass*0.4 + A.lowmid*0.2;
const fy=0.82*Hh;
blendMode(ADD); noStroke();
for(let i=0;i<nRay;i++){
  const spread=1.1;
  const cen=Math.PI/2; // straight down
  const baseAng=cen + lrp(-spread,spread,i/Math.max(1,nRay-1))*0.6;
  const ang=baseAng + globalSwing + Math.sin(K.t*0.4+i*1.7)*0.03*(0.5+en);
  const col=rayCol(i,nRay);
  const len=Hh*1.05;
  const hw=(u*0.018)*(0.6+P.scale*0.5); // half-width at apex
  const flare=len*0.14; // widening at far end
  const dx=Math.cos(ang), dy=Math.sin(ang);
  const px=-dy, py=dx; // perpendicular
  const a1=(bright*22)*(wire?0.5:1);
  // layered translucent quads for soft beam
  for(let L=0;L<3;L++){
    const w=hw*(1+L*0.8), fl=flare*(1+L*0.7);
    fill(col[0], chi?4:(ink?14:col[1]*0.9), col[2], a1*(1-L*0.28));
    beginShape();
    vertex(rx+px*w, ry+py*w);
    vertex(rx-px*w, ry-py*w);
    vertex(rx+dx*len-px*fl, ry+dy*len-py*fl);
    vertex(rx+dx*len+px*fl, ry+dy*len+py*fl);
    endShape(CLOSE);
  }
}

// ---- rose window live glow (breathe on beat/bass) ----
const rg=bright*(0.7+K.pulse*0.4+A.bass*0.5);
for(let r=0;r<4;r++){
  const col=rayCol(r*2%6,6);
  fill(col[0], chi?6:60, chi?90:100, (10+rg*22)*(1-r*0.2));
  ellipse(rx,ry,rR*(0.8+r*0.6)*(1+rg*0.2),rR*(0.8+r*0.6)*(1+rg*0.2));
}
// treble sparkle in rose tracery
if(A.treble>0.05){for(let i=0;i<8;i++){const a=i/8*6.2832; fill(md(H+i*30,360),40,100,A.treble*50); ellipse(rx+Math.cos(a)*rR*0.6,ry+Math.sin(a)*rR*0.6,u*0.006,u*0.006);}}

// ---- dust motes drifting in the light (real-time via K.t) ----
const nD=Math.round(S.dust.length*clp(P.density,0.15,1));
for(let i=0;i<nD;i++){
  const d=S.dust[i];
  const dx2=frc(d.x + Math.sin(K.t*0.05*d.sp+d.ph)*0.04 + K.t*0.004*d.sp)*W;
  const dy2=frc(d.y - K.t*0.006*d.sp + Math.sin(K.t*0.08+d.ph)*0.02)*Hh;
  // brighter near rose column of light
  const near=clp(1-Math.abs(dx2-rx)/(W*0.5),0,1);
  const tw=0.5+0.5*Math.sin(K.t*(1+d.s)+d.ph);
  fill(md(H+30,360),20,100, bright*near*tw*30*d.s);
  ellipse(dx2,dy2,u*0.0035*d.s,u*0.0035*d.s);
}
blendMode(BLEND);
